// Forecast/PM2.5/UV all update far less often (~every 30min-1hr) than the
// live temp/humidity readings above, so cache them in workflow static data
// and only re-fetch once the cache is stale. This cuts data.gov.sg API
// calls roughly 6x since this workflow still runs every 5 minutes.
const cfg = $('Config (edit per location)').item.json;
const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const CACHE_MS = 30 * 60 * 1000;

if (staticData.slowWeather && (now - staticData.slowWeather.cachedAt) < CACHE_MS) {
  return [{ json: staticData.slowWeather.data }];
}

const headers = { 'x-api-key': cfg.DATA_GOV_SG_API_KEY };

const sgDate = new Date(now + 8 * 60 * 60 * 1000).toISOString().slice(0, 10);

const [forecastResp, pm25Resp, moonResp] = await Promise.all([
  this.helpers.httpRequest({ method: 'GET', url: 'https://api-open.data.gov.sg/v2/real-time/api/two-hr-forecast', headers, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: 'https://api-open.data.gov.sg/v2/real-time/api/pm25', headers, json: true }),
  // USNO (US Naval Observatory) - authoritative, free, no API key - gives
  // the current named moon phase (curphase) directly, so no local synodic
  // calculation is needed for the moon-phase icon below.
  this.helpers.httpRequest({ method: 'GET', url: `https://aa.usno.navy.mil/api/rstt/oneday?date=${sgDate}&coords=${cfg.HOME_LAT},${cfg.HOME_LON}&tz=8`, json: true }),
]);

const data = { forecast: forecastResp.data, pm25: pm25Resp.data, moon: moonResp.properties && moonResp.properties.data };
staticData.slowWeather = { cachedAt: now, data };

return [{ json: data }];

// Both the sensor readings and the forecast/PM2.5 come from a network of
// stations/areas/regions, not a single point - pick whichever is
// physically closest to home for each.
const cfg = $('Config (edit per location)').item.json;
const tempResp = $('Fetch Air Temperature (data.gov.sg)').item.json.data;
const humResp = $('Fetch Relative Humidity (data.gov.sg)').item.json.data;
const slow = $input.first().json;
const forecastResp = slow.forecast;
const pm25Resp = slow.pm25;

function haversineKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function nearestReading(resp) {
  const stationsById = Object.fromEntries(resp.stations.map(s => [s.id, s.location]));
  const readings = resp.readings[0].data;
  const withDist = readings
    .filter(r => stationsById[r.stationId])
    .map(r => ({
      value: r.value,
      distanceKm: haversineKm(cfg.HOME_LAT, cfg.HOME_LON, stationsById[r.stationId].latitude, stationsById[r.stationId].longitude)
    }))
    .sort((a, b) => a.distanceKm - b.distanceKm);
  return withDist[0].value;
}

function nearestForecast(resp) {
  const areasByName = Object.fromEntries(resp.area_metadata.map(a => [a.name, a.label_location]));
  const forecasts = resp.items[0].forecasts;
  const withDist = forecasts
    .filter(f => areasByName[f.area])
    .map(f => ({
      forecast: f.forecast,
      distanceKm: haversineKm(cfg.HOME_LAT, cfg.HOME_LON, areasByName[f.area].latitude, areasByName[f.area].longitude)
    }))
    .sort((a, b) => a.distanceKm - b.distanceKm);
  return { forecast: withDist[0].forecast, validPeriodText: resp.items[0].valid_period.text };
}

function nearestPM25(resp) {
  const regionsByName = Object.fromEntries(resp.regionMetadata.map(r => [r.name, r.labelLocation]));
  const readings = resp.items[0].readings.pm25_one_hourly;
  const withDist = Object.entries(readings)
    .filter(([name]) => regionsByName[name])
    .map(([name, value]) => ({
      value,
      distanceKm: haversineKm(cfg.HOME_LAT, cfg.HOME_LON, regionsByName[name].latitude, regionsByName[name].longitude)
    }))
    .sort((a, b) => a.distanceKm - b.distanceKm);
  return withDist[0].value;
}

// Compacts a data.gov.sg valid_period string like
// "5.00 pm to 7.00 pm" into "5-7PM" for the small clock display.
function compactPeriod(text) {
  const m = text.match(/(\d{1,2})[.:]\d{2}\s*(am|pm)\s*to\s*(\d{1,2})[.:]\d{2}\s*(am|pm)/i);
  if (!m) return text.toUpperCase();
  const [, h1, ap1, h2, ap2] = m;
  return ap1.toLowerCase() === ap2.toLowerCase()
    ? `${h1}-${h2}${ap2.toUpperCase()}`
    : `${h1}${ap1.toUpperCase()}-${h2}${ap2.toUpperCase()}`;
}

// Maps data.gov.sg 2-hour forecast strings to AWTRIX icon IDs - added to
// the clock manually via its web UI (Icons -> Fetch from LaMetric gallery
// by ID -> Save to AWTRIX), not uploaded by this workflow or any script.
// See README for the full list of IDs this workflow needs. Picked to match
// https://flows.blueforcer.de/flow/QZ0sO0JQb7ut, extended to cover the
// extra conditions data.gov.sg reports that open-meteo doesn't. Singapore
// never reports snow, so unlike that flow's source there's no snow icon.
const FORECAST_ICON = {
  'Fair': '53386',
  'Fair (Day)': '53386',
  'Fair (Night)': '53386',
  'Fair and Warm': '53386',
  'Partly Cloudy': '2286',
  'Partly Cloudy (Day)': '2286',
  'Partly Cloudy (Night)': '2286',
  'Cloudy': '53384',
  'Hazy': '17055',
  'Slightly Hazy': '17055',
  'Windy': '2286',
  'Mist': '17055',
  'Fog': '17055',
  'Light Rain': '2720',
  'Moderate Rain': '2720',
  'Heavy Rain': '49300',
  'Passing Showers': '2720',
  'Light Showers': '2720',
  'Showers': '49300',
  'Heavy Showers': '49300',
  'Thundery Showers': '29839',
  'Heavy Thundery Showers': '29839',
  'Heavy Thundery Showers with Gusty Winds': '29839'
};
const DEFAULT_ICON = '36637';

// Clear sky at night shows the current moon phase instead of the sun icon
// used for daytime 'Fair'. Named phase comes from USNO (see fetch node);
// this map covers the 8 primary/intermediate phases USNO's curphase
// returns, icon IDs from the LaMetric gallery (added to the clock
// manually, see README).
const MOON_PHASE_ICON = {
  'New Moon': '2318',
  'Waxing Crescent': '2317',
  'First Quarter': '2316',
  'Waxing Gibbous': '2315',
  'Full Moon': '2314',
  'Waning Gibbous': '2319',
  'Last Quarter': '2320',
  'Waning Crescent': '2321',
};

// Local synodic-month fallback, used only if USNO is unreachable or
// returns a phase name outside the map above.
function moonPhaseIconFallback(date) {
  const synodicMonthDays = 29.53058867;
  const knownNewMoonUtc = Date.UTC(2000, 0, 6, 18, 14, 0);
  const daysSince = (date.getTime() - knownNewMoonUtc) / 86400000;
  let phase = (daysSince % synodicMonthDays) / synodicMonthDays;
  if (phase < 0) phase += 1;
  const icons = ['2318', '2317', '2316', '2315', '2314', '2319', '2320', '2321'];
  const bucket = Math.floor(((phase + 1 / 16) % 1) * 8);
  return icons[bucket];
}

function moonPhaseIcon(moonData, date) {
  const name = moonData && moonData.curphase;
  if (name && MOON_PHASE_ICON[name]) return MOON_PHASE_ICON[name];
  return moonPhaseIconFallback(date);
}

// data.gov.sg's 2hr-forecast is really "the forecast for the upcoming ~2hr
// window", so it doubles as both "current conditions" and "next" - there's
// no finer-grained hourly forecast available from the API.
const { forecast: forecastText, validPeriodText } = nearestForecast(forecastResp);
const forecastIcon = forecastText === 'Fair (Night)' ? moonPhaseIcon(slow.moon, new Date()) : (FORECAST_ICON[forecastText] || DEFAULT_ICON);

const temp = Math.round(nearestReading(tempResp));
const hum = Math.round(nearestReading(humResp));
const weatherPayload = { text: `${temp}°C ${hum}%`, icon: forecastIcon, durationMs: 8000, textCase: 'upper' };

const forecastPayload = { text: `NEXT ${compactPeriod(validPeriodText)}`, icon: forecastIcon, durationMs: 8000, textCase: 'upper' };

// AWTRIX's "AQI" icon set - 12 severity tiers, also added manually via the
// clock's web UI (see README). Bands the raw PM2.5 reading (ug/m3) against
// each tier's icon.
const AQI_ICON_BANDS = [
  { max: 25, icon: '39706' },
  { max: 40, icon: '39709' },
  { max: 60, icon: '39710' },
  { max: 90, icon: '39711' },
  { max: 110, icon: '39712' },
  { max: 140, icon: '39713' },
  { max: 160, icon: '39714' },
  { max: 190, icon: '39715' },
  { max: 210, icon: '39716' },
  { max: 290, icon: '39717' },
  { max: 310, icon: '39718' },
];
const AQI_ICON_OVER_MAX = '39719';

function aqiIconFor(pm25) {
  const band = AQI_ICON_BANDS.find(b => pm25 <= b.max);
  return band ? band.icon : AQI_ICON_OVER_MAX;
}

const pm25 = Math.round(nearestPM25(pm25Resp));
const aqIcon = aqiIconFor(pm25);
const aqiPayload = { text: `PM2.5 ${pm25}`, icon: aqIcon, durationMs: 8000, textCase: 'upper' };

return [
  { json: { app: 'weather', payload: weatherPayload } },
  { json: { app: 'weather_forecast', payload: forecastPayload } },
  { json: { app: 'aqi', payload: aqiPayload } },
];
